<style>
  body {
    margin: 0;
    padding: 0;
    background: #f4f2ec;
    font-family: "SimSun", "Times New Roman", serif;
    display: flex;
    justify-content: center;
  }

  .page {
    position: relative;
    width: 600px;
    min-height: 850px;
    background-color: #f4f2ec;
    background-image:
      repeating-linear-gradient(0deg, transparent 0px, transparent 79px, rgba(150,150,180,0.15) 80px),
      repeating-linear-gradient(90deg, transparent 0px, transparent 79px, rgba(150,150,180,0.15) 80px);
    box-sizing: border-box;
    padding: 40px 30px 30px 30px;
    overflow: hidden;
  }

  .main-title {
    text-align: center;
    color: #17275c;
    font-size: 36px;
    font-weight: bold;
    letter-spacing: 4px;
    margin-top: 20px;
    margin-bottom: 10px;
  }

  .subtitle {
    text-align: center;
    color: #2b3a7a;
    font-size: 18px;
    margin-bottom: 30px;
  }

  .doc-box {
    background: #ffffff;
    border: 1px solid #333;
    padding: 25px 30px;
    font-family: "Times New Roman", Times, serif;
    color: #111;
  }

  .center {
    text-align: center;
  }

  .sec-header {
    font-size: 12px;
    line-height: 1.5;
    margin-bottom: 8px;
  }

  .sec-header .bold {
    font-weight: bold;
  }

  .hr-line {
    border: none;
    border-top: 1px solid #333;
    margin: 12px 0;
  }

  .form-title {
    font-size: 22px;
    font-weight: bold;
    text-align: center;
    margin: 10px 0 20px 0;
  }

  .checkbox-line {
    font-size: 11px;
    margin: 4px 0;
  }

  .fy-line {
    font-size: 11px;
    text-align: center;
    margin: 4px 0 10px 0;
  }

  .or-line {
    text-align: center;
    font-size: 11px;
    margin: 8px 0;
  }

  .transition-line {
    font-size: 11px;
    margin: 4px 0;
  }

  .period-line, .commission-line {
    text-align: center;
    font-size: 11px;
    margin: 4px 0;
  }

  .apple-logo {
    text-align: center;
    margin: 20px 0 6px 0;
    font-size: 26px;
  }

  .company-name {
    text-align: center;
    font-size: 20px;
    font-weight: bold;
    margin-bottom: 4px;
  }

  .exact-name {
    text-align: center;
    font-size: 10px;
    margin-bottom: 20px;
  }

  .two-col {
    display: flex;
    justify-content: space-between;
    font-size: 11px;
    margin-bottom: 18px;
  }

  .two-col .col {
    width: 48%;
    text-align: center;
  }

  .two-col .bold {
    font-weight: bold;
  }

  .caption-small {
    font-size: 9px;
    color: #333;
  }

  .phone-row {
    text-align: center;
    font-size: 11px;
    margin-bottom: 4px;
  }

  .phone-row .bold {
    font-weight: bold;
  }

  .seal-placeholder {
    width: 110px;
    height: 110px;
    border: 1px dashed #888;
    border-radius: 50%;
    margin: 25px auto 10px auto;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    font-size: 9px;
    color: #666;
    background: rgba(200,200,220,0.15);
  }

  .redbook {
    text-align: center;
    color: #c0392b;
    font-size: 24px;
    font-weight: bold;
    font-family: "KaiTi", "SimSun", serif;
    margin: 25px 0 10px 0;
  }

  .disclaimer {
    font-size: 11px;
    color: #333;
    margin-top: 10px;
  }
</style>
</head>
<body>

<div class="page">

