    <div class="two-col">
      <div class="col">
        <div class="bold">California</div>
        <div class="caption-small">(State or other jurisdiction<br>of incorporation or organization)</div>
      </div>
      <div class="col">
        <div class="bold">94-2404110</div>
        <div class="caption-small">(I.R.S. Employer Identification No.)</div>
      </div>
    </div>

    <div class="two-col">
      <div class="col">
        <div class="bold">One Apple Park Way</div>
        <div class="bold">Cupertino, California</div>
        <div class="caption-small">(Address of principal executive offices)</div>
      </div>
      <div class="col">
        <div class="bold">95014</div>
        <div class="caption-small">(Zip Code)</div>
      </div>
    </div>

    <div class="phone-row">
      <div class="bold">(408) 996-1010</div>
    </div>
    <div class="phone-row caption-small">(Registrant's telephone number, including area code)</div>

    <div class="seal-placeholder placeholder">
      [Seal: SEC Official Seal, centered]
    </div>

  </div>

  <div class="redbook">小红书@jerrygong</div>

  <div class="disclaimer">DisClaimers：文中所述皆自公开市场信息梳理</div>

</div>

</body>
</html>
